import pytest
from hypothesis import given, strategies as st
from solution import iscube


def ref_iscube(a):
    """Obviously-correct reference model via binary search."""
    assert type(a) == int
    if a == 0:
        return True
    x = -a if a < 0 else a
    lo, hi = 1, x
    # cube root of x (x>=1) is <= x, so root in [1, x]
    while lo <= hi:
        mid = (lo + hi) // 2
        c = mid * mid * mid
        if c == x:
            return True
        elif c < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return False


# --- explicit spec examples ---

@pytest.mark.parametrize(
    "a, expected",
    [
        (1, True),
        (2, False),
        (-1, True),
        (64, True),
        (0, True),
        (180, False),
    ],
)
def test_spec_examples(a, expected):
    assert iscube(a) is expected


def test_zero_is_cube():
    assert iscube(0) is True


def test_one_and_neg_one_are_cubes():
    assert iscube(1) is True
    assert iscube(-1) is True


def test_returns_strict_bool():
    for a in [1, 2, -1, 64, 0, 180, 8, -8, 27, -27, 9]:
        r = iscube(a)
        assert type(r) == bool
        assert r is True or r is False


# --- property-based tests (bounded for slow SUT) ---

@given(k=st.integers(min_value=-30, max_value=30))
def test_perfect_cubes_return_true(k):
    assert iscube(k * k * k) is True


@given(k=st.integers(min_value=1, max_value=30))
def test_positive_near_cube_plus_one_is_not_cube(k):
    # k^3 < k^3+1 < (k+1)^3 since gap = 3k^2+3k+1 > 1
    assert iscube(k * k * k + 1) is False


@given(k=st.integers(min_value=-30, max_value=-1))
def test_negative_near_cube_minus_one_is_not_cube(k):
    # (k-1)^3 < k^3-1 < k^3 for k <= -1, so strictly between cubes
    assert iscube(k * k * k - 1) is False


@given(a=st.integers(min_value=-2000, max_value=2000))
def test_sign_symmetry(a):
    # a = k^3 iff -a = (-k)^3
    assert iscube(a) == iscube(-a)


@given(a=st.integers(min_value=-2000, max_value=2000))
def test_equivalence_to_reference_model(a):
    assert iscube(a) is ref_iscube(a)


def test_exhaustive_small_range_matches_cube_set():
    cubes = {k * k * k for k in range(-10, 11)}
    for a in range(-1000, 1001):
        assert iscube(a) is (a in cubes)


@given(k=st.integers(min_value=-30, max_value=30))
def test_cube_root_roundtrip(k):
    c = k * k * k
    assert iscube(c) is True
    # neighbours of a non-trivial cube are not cubes
    if c >= 1:
        assert iscube(c + 1) is False
    if c <= -1:
        assert iscube(c - 1) is False
